<?php
session_start(); require_once __DIR__."/config/conexao.php";
$busca=trim($_GET['busca']??'');
$sql="SELECT * FROM quartos WHERE (LOWER(COALESCE(disponibilidade,'')) IN ('disponivel','disponível') OR LOWER(COALESCE(status,'')) IN ('disponivel','disponível'))";
if($busca!==''){$sql.=" AND (CAST(numero AS CHAR) LIKE ? OR descricao LIKE ?)";$v="%$busca%";$s=$conexao->prepare($sql." ORDER BY preco ASC");$s->bind_param('ss',$v,$v);$s->execute();$resultado=$s->get_result();}else{$resultado=$conexao->query($sql." ORDER BY preco ASC");}
function imagemQuarto($q){$img=trim((string)($q['imagem']??''));if($img!==''&&filter_var($img,FILTER_VALIDATE_URL))return $img;if($img!==''&&is_file(__DIR__."/assets/img/".$img))return "assets/img/".$img;if($img!==''&&is_file(__DIR__."/assets/".$img))return "assets/".$img;$id=(int)$q['id'];return "assets/img/quarto".(($id-1)%8+1).".jpg";}
